import com.rustybank.TellerTerminal;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

/**
 * TELLER TERMINAL PROGRAM
 */
public class LegacyTellerTerminal implements TellerTerminal {

    private final AccountStore store;
    private final InterestCalculator interestCalculator = new InterestCalculator();

    public LegacyTellerTerminal(AccountStore store) {
        this.store = store;
    }

    @Override
    public void openAccount(String accountId) {
        store.add(accountId);
    }

    @Override
    public void deposit(String accountId, String amount) {
        Account a = store.find(accountId);
        BigDecimal d = MoneyUtil.parse(amount);
        a.setBalance(a.getBalance().add(d));
    }

    @Override
    public void withdraw(String accountId, String amount) {
        Account a = store.find(accountId);
        BigDecimal d = MoneyUtil.parse(amount);
        if (d.compareTo(a.getBalance()) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        a.setBalance(a.getBalance().subtract(d));
    }

    @Override
    public String balance(String accountId) {
        return MoneyUtil.format(store.find(accountId).getBalance());
    }

    @Override
    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        Account a = store.find(accountId);
        BigDecimal rate;
        try {
            rate = new BigDecimal(annualRatePercent.trim());
        } catch (Exception e) {
            throw new IllegalArgumentException("INVALID RATE", e);
        }
        BigDecimal interest = interestCalculator.monthlyInterest(a.getBalance(), rate);
        a.setBalance(a.getBalance().add(interest));
        return MoneyUtil.format(interest);
    }

    @Override
    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        if (payeeIds == null || payeeIds.isEmpty()) {
            throw new IllegalArgumentException("NO PAYEES");
        }
        BigDecimal total = MoneyUtil.parse(amount);
        Account from = store.find(fromAccountId);
        if (total.compareTo(from.getBalance()) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }

        from.setBalance(from.getBalance().subtract(total));

        BigInteger totalCents = total.movePointRight(2).toBigInteger();
        int n = payeeIds.size();
        BigInteger[] divRem = totalCents.divideAndRemainder(BigInteger.valueOf(n));
        BigInteger shareCents = divRem[0];
        int remainder = divRem[1].intValue();

        List<String> results = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            BigInteger cents = shareCents.add(i < remainder ? BigInteger.ONE : BigInteger.ZERO);
            BigDecimal share = new BigDecimal(cents).movePointLeft(2);
            Account p = store.find(payeeIds.get(i));
            p.setBalance(p.getBalance().add(share));
            results.add(MoneyUtil.format(share));
        }
        return results;
    }

    @Override
    public String totalHoldings() {
        BigDecimal sum = BigDecimal.ZERO;
        for (Account a : store.all()) {
            sum = sum.add(a.getBalance());
        }
        return MoneyUtil.format(sum);
    }
}

